package config

import (
	"fmt"
	"net/url"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"time"
)

const (
	defaultAddress        = ":8080"
	defaultTimeoutSeconds = 30
	defaultMaxFileSizeMB  = 50
	defaultMaxPages       = 20
	// Each running job decodes and re-renders a whole document, so only a few of
	// them are allowed to hold that memory at the same time.
	defaultMaxConcurrentJobs = 4
	// A synchronous mask renders the same document the async runner does, so the
	// number of them in flight is bounded as well.
	defaultMaxConcurrentSync = 4
	// Requests waiting for a free slot still hold their upload in memory, so the
	// queue smooths a short burst instead of parking callers for a long time.
	defaultSyncQueueWaitSeconds = 10
	// Uploaded documents are the very PII the service masks, so they are dropped
	// from disk a day after the job stopped changing unless told otherwise.
	defaultJobRetentionHours = 24
	defaultModel             = "pii"
	defaultLang              = "ko"
	defaultSchema            = "oac"
)

const (
	// DefaultReadHeaderTimeout bounds how long a client may take to send its
	// request headers, so a connection that dribbles them out cannot hold a
	// server goroutine forever. The request body is deliberately left untimed
	// because a 50MB upload on a slow link is legitimate.
	DefaultReadHeaderTimeout = 15 * time.Second
	// DefaultIdleTimeout closes keep-alive connections that stopped sending
	// requests instead of keeping them open indefinitely.
	DefaultIdleTimeout = 60 * time.Second
	// DefaultShutdownTimeout is how long in-flight requests get to finish once a
	// shutdown signal arrives; a synchronous mask waits for the upstream call, so
	// it needs more than the upstream timeout to drain cleanly.
	DefaultShutdownTimeout = 45 * time.Second
)

type Config struct {
	Server  ServerConfig
	Upstage UpstageConfig
	Limits  LimitsConfig
	Storage StorageConfig
	Debug   DebugConfig
	Mock    MockConfig
}

type ServerConfig struct {
	Address       string
	PublicBaseURL string
	// ReadHeaderTimeout and IdleTimeout bound how long a connection may stay open
	// without making progress. ShutdownTimeout bounds the graceful drain.
	ReadHeaderTimeout time.Duration
	IdleTimeout       time.Duration
	ShutdownTimeout   time.Duration
}

type UpstageConfig struct {
	BaseURL    string
	AuthMode   string
	AuthToken  string
	AllowHosts []string
	Timeout    time.Duration
	Model      string
	Lang       string
	Schema     string
	Verbose    bool
}

type LimitsConfig struct {
	MaxFileSizeBytes  int64
	MaxPages          int
	MaxConcurrentJobs int
	MaxConcurrentSync int
	// SyncQueueWait is how long a synchronous request waits for a free processing
	// slot before it is rejected as busy. Zero rejects it right away.
	SyncQueueWait  time.Duration
	SupportedMIMEs []string
}

type StorageConfig struct {
	RootDir string
	// JobRetention is how long a finished job keeps its stored files. Zero disables
	// the cleanup and keeps everything.
	JobRetention time.Duration
}

type DebugConfig struct {
	EnableDebug bool
}

type MockConfig struct {
	EnableEmbeddedUpstageMock bool
}

func Load() (Config, error) {
	rootDir := envOrDefault("PII_MASKER_STORAGE_DIR", filepath.Join(".", "data"))
	baseURL := strings.TrimSpace(os.Getenv("PII_MASKER_UPSTAGE_BASE_URL"))
	mockEnabled := envBool("PII_MASKER_ENABLE_EMBEDDED_UPSTAGE_MOCK", false)
	if baseURL == "" && mockEnabled {
		baseURL = "http://localhost:8080/internal/mock/upstage/inference"
	}
	if baseURL == "" {
		baseURL = "http://localhost:8080/inference"
	}

	normalizedBaseURL, parsedBaseURL, err := normalizeEndpointURL(baseURL)
	if err != nil {
		return Config{}, err
	}

	cfg := Config{
		Server: ServerConfig{
			Address:           envOrDefault("PII_MASKER_ADDR", defaultAddress),
			PublicBaseURL:     strings.TrimRight(strings.TrimSpace(os.Getenv("PII_MASKER_PUBLIC_BASE_URL")), "/"),
			ReadHeaderTimeout: envSeconds("PII_MASKER_READ_HEADER_TIMEOUT_SECONDS", DefaultReadHeaderTimeout),
			IdleTimeout:       envSeconds("PII_MASKER_IDLE_TIMEOUT_SECONDS", DefaultIdleTimeout),
			ShutdownTimeout:   envSeconds("PII_MASKER_SHUTDOWN_TIMEOUT_SECONDS", DefaultShutdownTimeout),
		},
		Upstage: UpstageConfig{
			BaseURL:    normalizedBaseURL,
			AuthMode:   normalizeAuthMode(envOrDefault("PII_MASKER_UPSTAGE_AUTH_MODE", "bearer")),
			AuthToken:  strings.TrimSpace(os.Getenv("PII_MASKER_UPSTAGE_AUTH_TOKEN")),
			AllowHosts: normalizeAllowHosts(os.Getenv("PII_MASKER_ALLOW_HOSTS"), parsedBaseURL),
			Timeout:    time.Duration(envInt("PII_MASKER_DEFAULT_TIMEOUT_SECONDS", defaultTimeoutSeconds)) * time.Second,
			Model:      envOrDefault("PII_MASKER_DEFAULT_MODEL", defaultModel),
			Lang:       normalizePIILang(envOrDefault("PII_MASKER_DEFAULT_LANG", defaultLang)),
			Schema:     normalizePIISchema(envOrDefault("PII_MASKER_DEFAULT_SCHEMA", defaultSchema)),
			Verbose:    envBool("PII_MASKER_DEFAULT_VERBOSE", false),
		},
		Limits: LimitsConfig{
			MaxFileSizeBytes:  int64(envInt("PII_MASKER_MAX_FILE_SIZE_MB", defaultMaxFileSizeMB)) * 1024 * 1024,
			MaxPages:          envInt("PII_MASKER_MAX_PAGES", defaultMaxPages),
			MaxConcurrentJobs: envInt("PII_MASKER_MAX_CONCURRENT_JOBS", defaultMaxConcurrentJobs),
			MaxConcurrentSync: envInt("PII_MASKER_MAX_CONCURRENT_SYNC", defaultMaxConcurrentSync),
			SyncQueueWait:     time.Duration(envNonNegativeInt("PII_MASKER_SYNC_QUEUE_WAIT_SECONDS", defaultSyncQueueWaitSeconds)) * time.Second,
			SupportedMIMEs:    []string{"application/pdf", "image/png", "image/jpeg"},
		},
		Storage: StorageConfig{
			RootDir:      rootDir,
			JobRetention: time.Duration(envNonNegativeInt("PII_MASKER_JOB_RETENTION_HOURS", defaultJobRetentionHours)) * time.Hour,
		},
		Debug: DebugConfig{
			EnableDebug: envBool("PII_MASKER_ENABLE_DEBUG", false),
		},
		Mock: MockConfig{
			EnableEmbeddedUpstageMock: mockEnabled,
		},
	}

	if err := os.MkdirAll(cfg.Storage.RootDir, 0o755); err != nil {
		return Config{}, fmt.Errorf("failed to create storage dir: %w", err)
	}
	return cfg, nil
}

func normalizeEndpointURL(raw string) (string, *url.URL, error) {
	raw = strings.TrimSpace(raw)
	parsedURL, err := url.Parse(raw)
	if err != nil {
		return "", nil, fmt.Errorf("invalid upstream URL: %w", err)
	}
	if parsedURL.Scheme == "" || parsedURL.Host == "" {
		return "", nil, fmt.Errorf("upstream URL must include scheme and host")
	}
	parsedURL.Path = strings.TrimRight(parsedURL.Path, "/")
	if parsedURL.Path == "" {
		parsedURL.Path = "/inference"
	}
	return parsedURL.String(), parsedURL, nil
}

func normalizeAllowHosts(raw string, parsedBaseURL *url.URL) []string {
	parts := strings.Split(raw, ",")
	hosts := make([]string, 0, len(parts)+1)
	seen := map[string]struct{}{}

	appendHost := func(value string) {
		host := strings.ToLower(strings.TrimSpace(value))
		if host == "" {
			return
		}
		if _, ok := seen[host]; ok {
			return
		}
		seen[host] = struct{}{}
		hosts = append(hosts, host)
	}

	for _, part := range parts {
		appendHost(part)
	}
	if len(hosts) == 0 && parsedBaseURL != nil {
		appendHost(parsedBaseURL.Hostname())
	}
	return hosts
}

func normalizeAuthMode(value string) string {
	switch strings.ToLower(strings.TrimSpace(value)) {
	case "", "bearer":
		return "bearer"
	case "x-api-key":
		return "x-api-key"
	default:
		return "bearer"
	}
}

func normalizePIILang(value string) string {
	switch strings.ToLower(strings.TrimSpace(value)) {
	case "ko", "en", "ja", "zh":
		return strings.ToLower(strings.TrimSpace(value))
	default:
		return "ko"
	}
}

func normalizePIISchema(value string) string {
	switch strings.ToLower(strings.TrimSpace(value)) {
	case "", "oac":
		return "oac"
	case "ufp":
		return "ufp"
	default:
		return "oac"
	}
}

func envOrDefault(key, fallback string) string {
	value := strings.TrimSpace(os.Getenv(key))
	if value == "" {
		return fallback
	}
	return value
}

func envInt(key string, fallback int) int {
	value := strings.TrimSpace(os.Getenv(key))
	if value == "" {
		return fallback
	}
	parsed, err := strconv.Atoi(value)
	if err != nil || parsed <= 0 {
		return fallback
	}
	return parsed
}

// envSeconds reads a duration given in whole seconds. These guards protect the
// server from connections that never finish, so a non-positive value falls back
// to the default instead of disabling them.
func envSeconds(key string, fallback time.Duration) time.Duration {
	return time.Duration(envInt(key, int(fallback/time.Second))) * time.Second
}

// envNonNegativeInt accepts an explicit 0, which callers use to turn a limit off.
func envNonNegativeInt(key string, fallback int) int {
	value := strings.TrimSpace(os.Getenv(key))
	if value == "" {
		return fallback
	}
	parsed, err := strconv.Atoi(value)
	if err != nil || parsed < 0 {
		return fallback
	}
	return parsed
}

func envBool(key string, fallback bool) bool {
	value := strings.TrimSpace(os.Getenv(key))
	if value == "" {
		return fallback
	}
	switch strings.ToLower(value) {
	case "1", "true", "yes", "y", "on":
		return true
	case "0", "false", "no", "n", "off":
		return false
	default:
		return fallback
	}
}
package config

import (
	"testing"
	"time"
)

func TestLoadServerTimeoutDefaults(t *testing.T) {
	t.Setenv("PII_MASKER_STORAGE_DIR", t.TempDir())

	cfg, err := Load()
	if err != nil {
		t.Fatalf("load: %v", err)
	}

	if cfg.Server.ReadHeaderTimeout != DefaultReadHeaderTimeout {
		t.Fatalf("unexpected read header timeout %s", cfg.Server.ReadHeaderTimeout)
	}
	if cfg.Server.IdleTimeout != DefaultIdleTimeout {
		t.Fatalf("unexpected idle timeout %s", cfg.Server.IdleTimeout)
	}
	if cfg.Server.ShutdownTimeout != DefaultShutdownTimeout {
		t.Fatalf("unexpected shutdown timeout %s", cfg.Server.ShutdownTimeout)
	}
}

func TestLoadServerTimeoutOverrides(t *testing.T) {
	t.Setenv("PII_MASKER_STORAGE_DIR", t.TempDir())
	t.Setenv("PII_MASKER_READ_HEADER_TIMEOUT_SECONDS", "5")
	t.Setenv("PII_MASKER_IDLE_TIMEOUT_SECONDS", "7")
	t.Setenv("PII_MASKER_SHUTDOWN_TIMEOUT_SECONDS", "9")

	cfg, err := Load()
	if err != nil {
		t.Fatalf("load: %v", err)
	}

	if cfg.Server.ReadHeaderTimeout != 5*time.Second {
		t.Fatalf("unexpected read header timeout %s", cfg.Server.ReadHeaderTimeout)
	}
	if cfg.Server.IdleTimeout != 7*time.Second {
		t.Fatalf("unexpected idle timeout %s", cfg.Server.IdleTimeout)
	}
	if cfg.Server.ShutdownTimeout != 9*time.Second {
		t.Fatalf("unexpected shutdown timeout %s", cfg.Server.ShutdownTimeout)
	}
}

// A non-positive value would disable the guard, so it falls back to the default.
func TestLoadServerTimeoutRejectsNonPositiveValues(t *testing.T) {
	t.Setenv("PII_MASKER_STORAGE_DIR", t.TempDir())
	t.Setenv("PII_MASKER_READ_HEADER_TIMEOUT_SECONDS", "0")
	t.Setenv("PII_MASKER_IDLE_TIMEOUT_SECONDS", "-1")
	t.Setenv("PII_MASKER_SHUTDOWN_TIMEOUT_SECONDS", "abc")

	cfg, err := Load()
	if err != nil {
		t.Fatalf("load: %v", err)
	}

	if cfg.Server.ReadHeaderTimeout != DefaultReadHeaderTimeout {
		t.Fatalf("unexpected read header timeout %s", cfg.Server.ReadHeaderTimeout)
	}
	if cfg.Server.IdleTimeout != DefaultIdleTimeout {
		t.Fatalf("unexpected idle timeout %s", cfg.Server.IdleTimeout)
	}
	if cfg.Server.ShutdownTimeout != DefaultShutdownTimeout {
		t.Fatalf("unexpected shutdown timeout %s", cfg.Server.ShutdownTimeout)
	}
}
package upstage

import (
	"bytes"
	"context"
	"crypto/x509"
	"encoding/json"
	"errors"
	"fmt"
	"image/png"
	"io"
	"mime/multipart"
	"net"
	"net/http"
	"net/textproto"
	"net/url"
	"path/filepath"
	"strconv"
	"strings"
	"time"
	"unicode"

	"pii-masker/internal/config"
	"pii-masker/internal/document"
)

// maxUpstreamRedirects bounds how far a redirect chain from the inference endpoint
// may be followed before the request is abandoned.
const maxUpstreamRedirects = 5

// maxUpstreamResponseBytes bounds how much of an inference response is buffered.
// The whole body is held in memory while the document is re-rendered, so it has
// to be capped; a body that runs past the cap is reported as its own error
// instead of being decoded as truncated JSON.
const maxUpstreamResponseBytes = 8 * 1024 * 1024

type Client struct {
	config config.UpstageConfig
}

// blockedHostError marks an upstream target that is not on the configured allow
// list. It is also returned from CheckRedirect, so a redirect chain cannot carry
// the uploaded document or the API token to a host the operator never allowed.
type blockedHostError struct {
	host string
}

func (e *blockedHostError) Error() string {
	return fmt.Sprintf("host %q is not in the upstream allow list", e.host)
}

type ParseOptions struct {
	Model   string
	Lang    string
	Schema  string
	Verbose bool
}

type ParseResponse struct {
	Result         json.RawMessage `json:"result"`
	Type           string          `json:"type"`
	NumBilledPages int             `json:"numBilledPages"`
	API            string          `json:"api"`
	Content        struct {
		HTML     string `json:"html"`
		Markdown string `json:"markdown"`
		Text     string `json:"text"`
	} `json:"content"`
	Model string `json:"model"`
	Usage struct {
		Pages int `json:"pages"`
	} `json:"usage"`
}

type DocumentResult struct {
	Attachment document.Attachment
	Response   ParseResponse
	// RawBody is the complete response body as the endpoint sent it. The masking
	// engine reads its fields from here when the response is not wrapped in a
	// "result" envelope; ResponseDebug.Body is a truncated, pretty printed copy
	// meant for humans and must never be parsed.
	RawBody       []byte
	ResponseDebug ResponseDebug
	RequestDebug  RequestDebug
}

type RequestDebug struct {
	URL        string            `json:"url"`
	AuthMode   string            `json:"auth_mode"`
	Fields     map[string]string `json:"fields"`
	Attachment struct {
		Name      string `json:"name"`
		MIMEType  string `json:"mime_type"`
		Extension string `json:"extension"`
		Size      int64  `json:"size"`
	} `json:"attachment"`
}

type ResponseDebug struct {
	StatusCode int    `json:"status_code,omitempty"`
	RequestID  string `json:"request_id,omitempty"`
	ErrorCode  string `json:"error_code,omitempty"`
	Summary    string `json:"summary,omitempty"`
	Detail     string `json:"detail,omitempty"`
	Hint       string `json:"hint,omitempty"`
	Body       string `json:"body,omitempty"`
}

type ConnectionStatus struct {
	OK         bool   `json:"ok"`
	URL        string `json:"url"`
	StatusCode int    `json:"status_code"`
	Message    string `json:"message"`
	ErrorCode  string `json:"error_code,omitempty"`
	Detail     string `json:"detail,omitempty"`
	Hint       string `json:"hint,omitempty"`
	Retryable  bool   `json:"retryable"`
}

type CallError struct {
	Code        string
	Summary     string
	Detail      string
	Hint        string
	RequestURL  string
	StatusCode  int
	Retryable   bool
	InputDebug  string
	OutputDebug string
}

func NewClient(cfg config.UpstageConfig) *Client {
	return &Client{config: cfg}
}

func (e *CallError) Error() string {
	if e == nil {
		return ""
	}
	lines := []string{}
	if e.Summary != "" {
		lines = append(lines, e.Summary)
	}
	if e.Detail != "" {
		lines = append(lines, "상세: "+e.Detail)
	}
	if e.Hint != "" {
		lines = append(lines, "조치: "+e.Hint)
	}
	if e.StatusCode > 0 {
		lines = append(lines, fmt.Sprintf("HTTP 상태: %d", e.StatusCode))
	}
	return strings.Join(lines, "\n")
}

func (e *CallError) toConnectionStatus() ConnectionStatus {
	if e == nil {
		return ConnectionStatus{}
	}
	return ConnectionStatus{
		OK:         false,
		URL:        e.RequestURL,
		StatusCode: e.StatusCode,
		Message:    e.Summary,
		ErrorCode:  e.Code,
		Detail:     e.Detail,
		Hint:       e.Hint,
		Retryable:  e.Retryable,
	}
}

func (c *Client) ParseDocument(ctx context.Context, attachment document.Attachment, options ParseOptions) (DocumentResult, int, time.Duration, error) {
	fields := buildFormFields(c.config, options)
	upstreamAttachment, err := prepareUpstreamAttachment(attachment)
	requestDebug := buildRequestDebug(c.config, fields, upstreamAttachment)

	startedAt := time.Now()
	if err != nil {
		elapsed := time.Since(startedAt)
		callErr := newCallError(
			"upstream_prepare_failed",
			"JPG/JPEG 파일을 PII 추론용 형식으로 변환하지 못했습니다.",
			err.Error(),
			"손상되지 않은 JPG/JPEG 파일인지 확인한 뒤 다시 시도하세요.",
			c.config.BaseURL,
			0,
			false,
		)
		return DocumentResult{
			Attachment:   attachment,
			RequestDebug: requestDebug,
		}, 0, elapsed, callErr.withDebug(requestDebug, ResponseDebug{})
	}

	result, statusCode, err := c.performParseRequest(ctx, attachment, upstreamAttachment, fields, requestDebug)
	elapsed := time.Since(startedAt)
	return result, statusCode, elapsed, err
}

func (c *Client) TestConnection(ctx context.Context) (ConnectionStatus, error) {
	requestURL := buildRequestURL(c.config.BaseURL, c.config.Model)
	if err := c.checkHostAllowed(requestURL); err != nil {
		return classifyRequestError(requestURL, err).toConnectionStatus(), nil
	}

	var body bytes.Buffer
	writer := multipart.NewWriter(&body)
	if err := writer.WriteField("model", c.config.Model); err != nil {
		return ConnectionStatus{}, err
	}
	if err := writer.Close(); err != nil {
		return ConnectionStatus{}, err
	}

	request, err := http.NewRequestWithContext(ctx, http.MethodPost, requestURL, &body)
	if err != nil {
		return ConnectionStatus{}, err
	}
	request.Header.Set("Content-Type", writer.FormDataContentType())
	request.Header.Set("Accept", "application/json")
	applyAuthHeader(request, c.config)

	response, err := c.httpClient().Do(request)
	if err != nil {
		return classifyRequestError(c.config.BaseURL, err).toConnectionStatus(), nil
	}
	defer response.Body.Close()

	bodyBytes, _ := io.ReadAll(io.LimitReader(response.Body, 32*1024))
	switch response.StatusCode {
	case http.StatusBadRequest, http.StatusUnsupportedMediaType, http.StatusUnprocessableEntity:
		return ConnectionStatus{
			OK:         true,
			URL:        c.config.BaseURL,
			StatusCode: response.StatusCode,
			Message:    "엔드포인트 연결과 인증은 확인되었습니다. 테스트 요청은 문서 파일이 없어 예상대로 거부되었습니다.",
		}, nil
	}
	if response.StatusCode >= http.StatusBadRequest {
		return classifyHTTPError(c.config.BaseURL, response.StatusCode, response.Header, bodyBytes).toConnectionStatus(), nil
	}

	return ConnectionStatus{
		OK:         true,
		URL:        c.config.BaseURL,
		StatusCode: response.StatusCode,
		Message:    defaultIfEmpty(strings.TrimSpace(string(bodyBytes)), "연결에 성공했습니다."),
	}, nil
}

func (c *Client) performParseRequest(ctx context.Context, originalAttachment document.Attachment, upstreamAttachment document.Attachment, fields map[string]string, requestDebug RequestDebug) (DocumentResult, int, error) {
	requestURL := buildRequestURL(c.config.BaseURL, fields["model"])
	if err := c.checkHostAllowed(requestURL); err != nil {
		return DocumentResult{}, 0, attachDebug(classifyRequestError(requestURL, err), requestDebug, ResponseDebug{})
	}

	var body bytes.Buffer
	writer := multipart.NewWriter(&body)

	for key, value := range fields {
		if err := writer.WriteField(key, value); err != nil {
			return DocumentResult{}, 0, fmt.Errorf("failed to write %s field: %w", key, err)
		}
	}

	part, err := createDocumentPart(writer, upstreamAttachment)
	if err != nil {
		return DocumentResult{}, 0, err
	}
	if _, err := io.Copy(part, bytes.NewReader(upstreamAttachment.Content)); err != nil {
		return DocumentResult{}, 0, err
	}
	if err := writer.Close(); err != nil {
		return DocumentResult{}, 0, err
	}

	request, err := http.NewRequestWithContext(ctx, http.MethodPost, requestURL, &body)
	if err != nil {
		return DocumentResult{}, 0, fmt.Errorf("failed to build upstream request: %w", err)
	}
	request.Header.Set("Content-Type", writer.FormDataContentType())
	request.Header.Set("Accept", "application/json")
	applyAuthHeader(request, c.config)

	response, err := c.httpClient().Do(request)
	if err != nil {
		return DocumentResult{}, 0, attachDebug(classifyRequestError(c.config.BaseURL, err), requestDebug, ResponseDebug{})
	}
	defer response.Body.Close()

	// Reading one byte past the cap is what tells a body that merely fills it
	// apart from one that was cut short, so an oversized response is not handed
	// to the JSON decoder as if the endpoint had returned malformed output.
	responseBody, err := io.ReadAll(io.LimitReader(response.Body, maxUpstreamResponseBytes+1))
	if err != nil {
		callErr := newCallError("response_read_failed", "Upstage 응답 본문을 읽는 중 오류가 발생했습니다.", err.Error(), "Upstage 응답 크기 제한과 네트워크 상태를 확인하세요.", c.config.BaseURL, response.StatusCode, true)
		return DocumentResult{}, response.StatusCode, callErr.withDebug(requestDebug, buildResponseDebug(response.StatusCode, response.Header, nil, callErr))
	}
	oversized := len(responseBody) > maxUpstreamResponseBytes
	if oversized {
		responseBody = responseBody[:maxUpstreamResponseBytes]
	}

	// An error status is classified first even when the body is oversized: the
	// status says more about what went wrong than the size does.
	if response.StatusCode >= http.StatusBadRequest {
		callErr := classifyHTTPError(c.config.BaseURL, response.StatusCode, response.Header, responseBody)
		return DocumentResult{}, response.StatusCode, attachDebug(callErr, requestDebug, buildResponseDebug(response.StatusCode, response.Header, responseBody, callErr))
	}

	if oversized {
		detail := fmt.Sprintf("응답 본문이 허용 한도 %dMB 를 넘어 끝까지 읽지 못했습니다.", maxUpstreamResponseBytes/(1024*1024))
		callErr := newCallError("response_too_large", "Upstage 응답이 너무 커서 처리하지 못했습니다.", detail, "문서를 나눠서 요청해 페이지 수를 줄이거나 verbose 옵션을 끄고 다시 시도하세요.", c.config.BaseURL, response.StatusCode, false)
		return DocumentResult{}, response.StatusCode, callErr.withDebug(requestDebug, buildResponseDebug(response.StatusCode, response.Header, responseBody, callErr))
	}

	var parsed ParseResponse
	if err := json.Unmarshal(responseBody, &parsed); err != nil {
		callErr := newCallError("decode_failed", "Upstage 응답 JSON을 해석하지 못했습니다.", err.Error(), "엔드포인트 URL과 응답 형식을 확인하세요.", c.config.BaseURL, response.StatusCode, false)
		return DocumentResult{}, response.StatusCode, callErr.withDebug(requestDebug, buildResponseDebug(response.StatusCode, response.Header, responseBody, callErr))
	}
	if strings.TrimSpace(parsed.Model) == "" {
		parsed.Model = fields["model"]
	}

	return DocumentResult{
		Attachment:    originalAttachment,
		Response:      parsed,
		RawBody:       responseBody,
		ResponseDebug: buildResponseDebug(response.StatusCode, response.Header, responseBody, nil),
		RequestDebug:  requestDebug,
	}, response.StatusCode, nil
}

func prepareUpstreamAttachment(attachment document.Attachment) (document.Attachment, error) {
	if !strings.EqualFold(strings.TrimSpace(attachment.MIMEType), "image/jpeg") {
		return attachment, nil
	}

	imageValue, _, err := document.DecodeImage(attachment.Content)
	if err != nil {
		return document.Attachment{}, fmt.Errorf("failed to decode jpeg: %w", err)
	}

	var buffer bytes.Buffer
	if err := png.Encode(&buffer, imageValue); err != nil {
		return document.Attachment{}, fmt.Errorf("failed to encode png: %w", err)
	}

	converted := attachment
	converted.Content = buffer.Bytes()
	converted.Size = int64(buffer.Len())
	converted.MIMEType = "image/png"
	converted.Extension = "png"
	converted.Name = replaceExtension(attachment.Name, ".png")
	return converted, nil
}

func replaceExtension(name, ext string) string {
	baseExt := filepath.Ext(name)
	if baseExt == "" {
		return name + ext
	}
	return strings.TrimSuffix(name, baseExt) + ext
}

func buildFormFields(cfg config.UpstageConfig, options ParseOptions) map[string]string {
	fields := map[string]string{
		"model": defaultIfEmpty(strings.TrimSpace(options.Model), cfg.Model),
	}
	if lang := defaultIfEmpty(strings.TrimSpace(options.Lang), cfg.Lang); lang != "" {
		fields["lang"] = lang
	}
	if schema := defaultIfEmpty(strings.TrimSpace(options.Schema), cfg.Schema); schema != "" && schema != "oac" {
		fields["schema"] = schema
	}
	if options.Verbose || cfg.Verbose {
		fields["verbose"] = strconv.FormatBool(true)
	}
	return fields
}

func buildRequestURL(baseURL, model string) string {
	parsedURL, err := url.Parse(baseURL)
	if err != nil {
		return baseURL
	}
	query := parsedURL.Query()
	if strings.TrimSpace(model) != "" {
		query.Set("model", model)
	}
	parsedURL.RawQuery = query.Encode()
	return parsedURL.String()
}

func buildRequestDebug(cfg config.UpstageConfig, fields map[string]string, attachment document.Attachment) RequestDebug {
	debug := RequestDebug{
		URL:      buildRequestURL(cfg.BaseURL, fields["model"]),
		AuthMode: cfg.AuthMode,
		Fields:   cloneFields(fields),
	}
	debug.Attachment.Name = attachment.Name
	debug.Attachment.MIMEType = attachment.MIMEType
	debug.Attachment.Extension = attachment.Extension
	debug.Attachment.Size = attachment.Size
	return debug
}

func createDocumentPart(writer *multipart.Writer, attachment document.Attachment) (io.Writer, error) {
	headers := make(textproto.MIMEHeader)
	headers.Set("Content-Disposition", fmt.Sprintf(`form-data; name="document"; filename="%s"`, escapeMultipartValue(attachment.Name)))
	headers.Set("Content-Type", defaultIfEmpty(strings.TrimSpace(attachment.MIMEType), "application/octet-stream"))
	return writer.CreatePart(headers)
}

// escapeMultipartValue prepares a value for a quoted multipart header parameter.
// Control characters are dropped instead of escaped because a CR or LF would end
// the header line and let the value inject headers into the upstream request.
func escapeMultipartValue(value string) string {
	var builder strings.Builder
	builder.Grow(len(value))
	for _, r := range value {
		switch {
		case unicode.IsControl(r):
			continue
		case r == '\\', r == '"':
			builder.WriteByte('\\')
			builder.WriteRune(r)
		default:
			builder.WriteRune(r)
		}
	}
	return builder.String()
}

func applyAuthHeader(request *http.Request, cfg config.UpstageConfig) {
	if cfg.AuthToken == "" {
		return
	}
	if cfg.AuthMode == "x-api-key" {
		request.Header.Set("x-api-key", cfg.AuthToken)
		return
	}
	request.Header.Set("Authorization", "Bearer "+cfg.AuthToken)
}

func (c *Client) httpClient() *http.Client {
	timeout := c.config.Timeout
	if timeout <= 0 {
		timeout = 30 * time.Second
	}
	return &http.Client{
		Timeout: timeout,
		CheckRedirect: func(request *http.Request, via []*http.Request) error {
			if len(via) >= maxUpstreamRedirects {
				return fmt.Errorf("stopped after %d redirects", maxUpstreamRedirects)
			}
			return c.checkURLAllowed(request.URL)
		},
	}
}

// allowedHosts lists the hosts this client may talk to. An empty configuration
// falls back to the host of the configured base URL, so the client can never be
// left without a target restriction.
func (c *Client) allowedHosts() []string {
	if len(c.config.AllowHosts) > 0 {
		return c.config.AllowHosts
	}
	parsedURL, err := url.Parse(c.config.BaseURL)
	if err != nil {
		return nil
	}
	if host := parsedURL.Hostname(); host != "" {
		return []string{host}
	}
	return nil
}

// checkHostAllowed rejects a target URL before any request body is built.
func (c *Client) checkHostAllowed(rawURL string) error {
	parsedURL, err := url.Parse(rawURL)
	if err != nil {
		return &blockedHostError{host: rawURL}
	}
	return c.checkURLAllowed(parsedURL)
}

func (c *Client) checkURLAllowed(target *url.URL) error {
	if hostAllowed(target, c.allowedHosts()) {
		return nil
	}
	return &blockedHostError{host: target.Host}
}

// hostAllowed matches target against the allow list entries, which may be written
// either as a bare host name or with an explicit port.
func hostAllowed(target *url.URL, allowed []string) bool {
	if target == nil {
		return false
	}
	hostname := strings.ToLower(target.Hostname())
	hostPort := strings.ToLower(target.Host)
	if hostname == "" {
		return false
	}
	for _, entry := range allowed {
		entry = strings.ToLower(strings.TrimSpace(entry))
		if entry == "" {
			continue
		}
		if entry == hostname || entry == hostPort {
			return true
		}
	}
	return false
}

func cloneFields(fields map[string]string) map[string]string {
	copied := make(map[string]string, len(fields))
	for key, value := range fields {
		copied[key] = value
	}
	return copied
}

func buildResponseDebug(statusCode int, headers http.Header, body []byte, callErr *CallError) ResponseDebug {
	responseDebug := ResponseDebug{
		StatusCode: statusCode,
		RequestID:  firstHeaderValue(headers, "X-Request-Id", "X-Request-ID", "X-Correlation-ID"),
		Body:       formatDebugBody(body),
	}
	if callErr != nil {
		responseDebug.ErrorCode = callErr.Code
		responseDebug.Summary = callErr.Summary
		responseDebug.Detail = callErr.Detail
		responseDebug.Hint = callErr.Hint
	}
	return responseDebug
}

func formatDebugBody(body []byte) string {
	trimmed := bytes.TrimSpace(body)
	if len(trimmed) == 0 {
		return ""
	}
	var payload any
	if err := json.Unmarshal(trimmed, &payload); err == nil {
		if pretty, err := json.MarshalIndent(payload, "", "  "); err == nil {
			return truncateString(string(pretty), 16*1024)
		}
	}
	return truncateString(string(trimmed), 16*1024)
}

func attachDebug(err error, requestDebug RequestDebug, responseDebug ResponseDebug) error {
	var callErr *CallError
	if !errors.As(err, &callErr) {
		return err
	}
	return callErr.withDebug(requestDebug, responseDebug)
}

func (e *CallError) withDebug(requestDebug RequestDebug, responseDebug ResponseDebug) *CallError {
	if e == nil {
		return nil
	}
	copyErr := *e
	copyErr.InputDebug = marshalDebugPayload(requestDebug)
	copyErr.OutputDebug = marshalDebugPayload(responseDebug)
	return &copyErr
}

func marshalDebugPayload(payload any) string {
	raw, err := json.MarshalIndent(payload, "", "  ")
	if err != nil {
		return ""
	}
	return string(raw)
}

func newCallError(code, summary, detail, hint, requestURL string, statusCode int, retryable bool) *CallError {
	return &CallError{
		Code:       strings.TrimSpace(code),
		Summary:    strings.TrimSpace(summary),
		Detail:     strings.TrimSpace(detail),
		Hint:       strings.TrimSpace(hint),
		RequestURL: strings.TrimSpace(requestURL),
		StatusCode: statusCode,
		Retryable:  retryable,
	}
}

func classifyHTTPError(requestURL string, statusCode int, headers http.Header, body []byte) *CallError {
	bodySummary := summarizeResponseBody(body)
	requestID := firstHeaderValue(headers, "X-Request-Id", "X-Request-ID", "X-Correlation-ID")
	if requestID != "" {
		bodySummary = strings.TrimSpace(bodySummary + " (Upstage request id: " + requestID + ")")
	}

	switch statusCode {
	case http.StatusBadRequest:
		return newCallError("bad_request", "PII 추론 요청이 거부되었습니다.", defaultIfEmpty(bodySummary, "입력 문서 또는 파라미터 형식이 PII API 요구사항과 맞지 않습니다."), "model, lang, schema, verbose 값과 업로드 문서 형식을 확인하세요.", requestURL, statusCode, false)
	case http.StatusUnauthorized, http.StatusForbidden:
		return newCallError("auth_failed", "PII API 인증에 실패했습니다.", defaultIfEmpty(bodySummary, "API 키가 유효하지 않거나 권한이 없습니다."), "인증 토큰과 헤더 방식을 확인하세요.", requestURL, statusCode, false)
	case http.StatusNotFound:
		return newCallError("not_found", "PII API 엔드포인트를 찾지 못했습니다.", defaultIfEmpty(bodySummary, "/inference 경로가 올바르지 않습니다."), "기본 URL이 /inference 엔드포인트인지 확인하세요.", requestURL, statusCode, false)
	case http.StatusTooManyRequests:
		return newCallError("rate_limited", "PII API 호출 한도에 걸렸습니다.", defaultIfEmpty(bodySummary, "잠시 후 다시 시도해야 합니다."), "요청 빈도를 줄이거나 잠시 후 다시 시도하세요.", requestURL, statusCode, true)
	case http.StatusRequestEntityTooLarge:
		return newCallError("file_too_large", "업로드한 문서 파일이 너무 큽니다.", defaultIfEmpty(bodySummary, "PII API가 파일 크기 제한을 초과한 요청을 거부했습니다."), "50MB 이하 파일인지 확인하고, 필요하면 파일을 분할하세요.", requestURL, statusCode, false)
	case http.StatusUnsupportedMediaType:
		return newCallError("unsupported_media_type", "PII API가 이 문서 형식을 지원하지 않습니다.", defaultIfEmpty(bodySummary, "지원되지 않는 파일 형식입니다."), "PDF 또는 PNG 파일인지 확인하세요.", requestURL, statusCode, false)
	default:
		if statusCode >= http.StatusInternalServerError {
			return newCallError("server_error", "PII API 서버 내부 오류가 발생했습니다.", defaultIfEmpty(bodySummary, "PII API 서버가 5xx 오류를 반환했습니다."), "잠시 후 다시 시도하고, 반복되면 Upstage 서버 상태와 로그를 확인하세요.", requestURL, statusCode, true)
		}
		return newCallError("unexpected_status", fmt.Sprintf("PII API가 예상하지 못한 HTTP 상태 %d 를 반환했습니다.", statusCode), bodySummary, "응답 본문과 PII API 설정을 함께 확인하세요.", requestURL, statusCode, statusCode >= 500)
	}
}

func classifyRequestError(requestURL string, err error) *CallError {
	detail := strings.TrimSpace(err.Error())

	// A blocked host is reported before the request leaves and from CheckRedirect,
	// so both paths land here wrapped in the same *url.Error the transport returns.
	var blockedHost *blockedHostError
	if errors.As(err, &blockedHost) {
		return newCallError("upstream_host_not_allowed", "허용되지 않은 호스트로 PII API를 호출하려고 했습니다.", detail, "PII_MASKER_ALLOW_HOSTS에 해당 호스트를 추가하거나 기본 URL을 확인하세요.", requestURL, 0, false)
	}

	var timeoutErr interface{ Timeout() bool }
	if errors.As(err, &timeoutErr) && timeoutErr.Timeout() {
		return newCallError("network_timeout", "PII API 서버 연결이 시간 초과되었습니다.", detail, "PII API 서버 상태와 네트워크 지연, 타임아웃 설정을 확인하세요.", requestURL, 0, true)
	}
	if errors.Is(err, context.DeadlineExceeded) {
		return newCallError("network_timeout", "PII API 서버 연결이 시간 초과되었습니다.", detail, "PII API 서버 상태와 타임아웃 값을 확인하세요.", requestURL, 0, true)
	}

	var dnsErr *net.DNSError
	if errors.As(err, &dnsErr) {
		return newCallError("dns_error", "PII API 호스트 이름을 찾지 못했습니다.", detail, "기본 URL의 도메인 이름과 DNS 설정을 확인하세요.", requestURL, 0, false)
	}

	var hostnameErr x509.HostnameError
	if errors.As(err, &hostnameErr) {
		return newCallError("tls_hostname_error", "TLS 인증서의 호스트 이름이 PII API URL과 일치하지 않습니다.", detail, "인증서의 SAN/CN과 기본 URL 호스트가 일치하는지 확인하세요.", requestURL, 0, false)
	}

	var unknownAuthorityErr x509.UnknownAuthorityError
	if errors.As(err, &unknownAuthorityErr) {
		return newCallError("tls_untrusted_ca", "PII API TLS 인증서를 신뢰할 수 없습니다.", detail, "서버 인증서 체인과 신뢰 저장소를 확인하세요.", requestURL, 0, false)
	}

	return newCallError("network_error", "PII API 서버에 연결하지 못했습니다.", detail, "서버 주소, 방화벽, 네트워크 연결 상태를 확인하세요.", requestURL, 0, true)
}

func summarizeResponseBody(body []byte) string {
	text := extractTextFromBody(body)
	if text != "" {
		return truncateString(text, 280)
	}
	return truncateString(strings.TrimSpace(string(body)), 280)
}

func extractTextFromBody(body []byte) string {
	var payload any
	if err := json.Unmarshal(body, &payload); err != nil {
		return strings.TrimSpace(string(body))
	}
	text := extractTextFromValue(payload)
	if text != "" {
		return text
	}
	pretty, err := json.MarshalIndent(payload, "", "  ")
	if err != nil {
		return ""
	}
	return string(pretty)
}

func extractTextFromValue(value any) string {
	candidates := make([]string, 0, 8)
	collectTextCandidates(value, &candidates)
	best := ""
	for _, candidate := range candidates {
		candidate = strings.TrimSpace(candidate)
		if candidate == "" {
			continue
		}
		if len(candidate) > len(best) {
			best = candidate
		}
	}
	return best
}

func collectTextCandidates(value any, candidates *[]string) {
	switch typed := value.(type) {
	case map[string]any:
		for key, nested := range typed {
			lowerKey := strings.ToLower(key)
			if isLikelyTextKey(lowerKey) {
				switch nestedValue := nested.(type) {
				case string:
					*candidates = append(*candidates, nestedValue)
				case map[string]any, []any:
					collectTextCandidates(nestedValue, candidates)
				}
				continue
			}
			collectTextCandidates(nested, candidates)
		}
	case []any:
		for _, item := range typed {
			collectTextCandidates(item, candidates)
		}
	case string:
		if strings.TrimSpace(typed) != "" {
			*candidates = append(*candidates, typed)
		}
	}
}

func isLikelyTextKey(key string) bool {
	return strings.Contains(key, "text") ||
		strings.Contains(key, "message") ||
		strings.Contains(key, "output") ||
		strings.Contains(key, "result") ||
		strings.Contains(key, "content") ||
		strings.Contains(key, "response") ||
		strings.Contains(key, "detail") ||
		strings.Contains(key, "error")
}

func truncateString(value string, maxLength int) string {
	value = strings.TrimSpace(value)
	if maxLength <= 0 || len(value) <= maxLength {
		return value
	}
	if maxLength <= 3 {
		return value[:maxLength]
	}
	return value[:maxLength-3] + "..."
}

func defaultIfEmpty(value, fallback string) string {
	if strings.TrimSpace(value) == "" {
		return fallback
	}
	return value
}

func firstHeaderValue(headers http.Header, names ...string) string {
	for _, name := range names {
		if value := strings.TrimSpace(headers.Get(name)); value != "" {
			return value
		}
	}
	return ""
}

package httpapi

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"mime/multipart"
	"net/http"
	"net/textproto"
	"os"
	"strconv"
	"strings"
	"unicode"

	"github.com/gorilla/mux"

	"pii-masker/internal/config"
	"pii-masker/internal/core"
	"pii-masker/internal/document"
	"pii-masker/internal/service"
	"pii-masker/internal/upstage"
)

const (
	// Multipart framing and the small text fields sent alongside the upload are the
	// only bytes allowed on top of the configured file size limit.
	uploadBodyHeadroomBytes = 64 * 1024
	// Parts above this size are spilled to a temp file instead of being buffered in
	// memory, so a large upload cannot pin the whole file in RAM twice.
	uploadMemoryBytes = 8 * 1024 * 1024
	// A shed request only waited for a slot, so retrying it shortly is worthwhile.
	retryAfterSeconds = "5"
	// The history listing is a convenience view of the most recent work, so a
	// caller that asks for nothing gets a page and one that asks for an absurd
	// number gets capped instead of having the whole store serialized for it.
	defaultHistoryLimit = 20
	maxHistoryLimit     = 100
)

type Server struct {
	config  config.Config
	service *service.Service
	router  *mux.Router
}

// payloadTooLargeError marks a request body that was cut off before the upload
// could be parsed, which is reported as 413 instead of a generic 400.
type payloadTooLargeError struct {
	limit int64
}

func (e *payloadTooLargeError) Error() string {
	return fmt.Sprintf("request body exceeds the maximum size of %d bytes", e.limit)
}

func New(cfg config.Config, svc *service.Service) *Server {
	server := &Server{
		config:  cfg,
		service: svc,
		router:  mux.NewRouter(),
	}
	server.routes()
	return server
}

func (s *Server) Handler() http.Handler {
	return s.router
}

func (s *Server) Mount(pathPrefix string, handler http.Handler) {
	s.router.PathPrefix(pathPrefix).Handler(handler)
}

func (s *Server) routes() {
	s.router.HandleFunc("/", s.handleIndex).Methods(http.MethodGet)
	s.router.HandleFunc("/ui", s.handleIndex).Methods(http.MethodGet)
	s.router.HandleFunc("/v1/health", s.handleHealth).Methods(http.MethodGet)
	s.router.HandleFunc("/v1/config/public", s.handlePublicConfig).Methods(http.MethodGet)
	s.router.HandleFunc("/v1/test-connection", s.handleTestConnection).Methods(http.MethodPost)
	s.router.HandleFunc("/v1/mask", documentResponse(s.handleMask)).Methods(http.MethodPost)
	s.router.HandleFunc("/v1/jobs", documentResponse(s.handleCreateJob)).Methods(http.MethodPost)
	s.router.HandleFunc("/v1/jobs/{job_id}", documentResponse(s.handleGetJob)).Methods(http.MethodGet)
	// HEAD is opened on the result only: http.ServeContent already answers it with the
	// same headers and no body, so download managers and proxies can probe size and
	// existence. The JSON endpoints do not set Content-Length themselves, so HEAD
	// would mean something different there and stays closed.
	s.router.HandleFunc("/v1/jobs/{job_id}/result", documentResponse(s.handleGetJobResult)).Methods(http.MethodGet, http.MethodHead)
	s.router.HandleFunc("/v1/history", documentResponse(s.handleHistory)).Methods(http.MethodGet)
}

// documentResponse wraps the endpoints whose responses carry an uploaded document or
// the metadata derived from it, which is the very PII the service was handed.
//
// Nothing on that path may keep a copy: a 200 response to a GET with no freshness
// directive is heuristically cacheable, and the result download hands out a
// Last-Modified that invites exactly that, so a shared proxy or the browser disk cache
// could still serve a masked file long after the retention sweep deleted it from disk.
// nosniff keeps a client from second-guessing the declared type on the way out.
func documentResponse(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Cache-Control", "no-store")
		w.Header().Set("X-Content-Type-Options", "nosniff")
		next(w, r)
	}
}

func (s *Server) handleHealth(w http.ResponseWriter, _ *http.Request) {
	writeJSON(w, http.StatusOK, map[string]any{"status": "ok"})
}

func (s *Server) handlePublicConfig(w http.ResponseWriter, _ *http.Request) {
	writeJSON(w, http.StatusOK, map[string]any{
		"limits": map[string]any{
			"max_file_size_bytes": s.config.Limits.MaxFileSizeBytes,
			"max_pages":           s.config.Limits.MaxPages,
		},
		"supported_types": s.config.Limits.SupportedMIMEs,
		"async_enabled":   true,
		"response_mode":   "multipart/mixed",
	})
}

func (s *Server) handleTestConnection(w http.ResponseWriter, r *http.Request) {
	status, err := s.service.TestConnection(r.Context())
	if err != nil {
		writeError(w, http.StatusBadGateway, &core.APIError{
			Code:    "connection_test_failed",
			Message: err.Error(),
		})
		return
	}
	writeJSON(w, http.StatusOK, status)
}

func (s *Server) handleMask(w http.ResponseWriter, r *http.Request) {
	input, err := s.readProcessInput(w, r)
	if err != nil {
		writeUploadError(w, err)
		return
	}

	metadata, maskedContent, processErr := s.service.ProcessSync(r.Context(), input)
	if processErr != nil {
		statusCode := http.StatusBadGateway
		var busy *service.ServerBusyError
		switch {
		case errors.As(processErr, &busy):
			// Nothing was processed, so the caller can safely send the same upload again.
			statusCode = http.StatusServiceUnavailable
			w.Header().Set("Retry-After", retryAfterSeconds)
		case metadata != nil && metadata.Error != nil && metadata.Error.Code == "processing_failed":
			statusCode = http.StatusBadRequest
		}
		writeJSON(w, statusCode, metadata)
		return
	}

	metadata.Output.Inline = true
	s.writeMultipartResponse(w, metadata, maskedContent)
}

func (s *Server) handleCreateJob(w http.ResponseWriter, r *http.Request) {
	input, err := s.readProcessInput(w, r)
	if err != nil {
		writeUploadError(w, err)
		return
	}

	job, err := s.service.CreateJob(r.Context(), input)
	if err != nil {
		var invalidInput *service.InvalidInputError
		if errors.As(err, &invalidInput) {
			writeError(w, http.StatusBadRequest, &core.APIError{
				Code:    "invalid_request",
				Message: err.Error(),
			})
			return
		}
		writeError(w, http.StatusInternalServerError, &core.APIError{
			Code:    "job_create_failed",
			Message: err.Error(),
		})
		return
	}
	job.Metadata.Output.DownloadURL = service.JoinPublicURL(s.config.Server.PublicBaseURL, "v1", "jobs", job.ID, "result")
