	// only bytes allowed on top of the configured file size limit.
	uploadBodyHeadroomBytes = 64 * 1024
	// Parts above this size are spilled to a temp file instead of being buffered in
	// memory, so a large upload cannot pin the whole file in RAM twice.
	uploadMemoryBytes = 8 * 1024 * 1024
	// A shed request only waited for a slot, so retrying it shortly is worthwhile.
	retryAfterSeconds = "5"
	// The history listing is a convenience view of the most recent work, so a
	// caller that asks for nothing gets a page and one that asks for an absurd
	// number gets capped instead of having the whole store serialized for it.
	defaultHistoryLimit = 20
	maxHistoryLimit     = 100
)

type Server struct {
	config  config.Config
	service *service.Service
	router  *mux.Router
}

// payloadTooLargeError marks a request body that was cut off before the upload
// could be parsed, which is reported as 413 instead of a generic 400.
type payloadTooLargeError struct {
	limit int64
}

func (e *payloadTooLargeError) Error() string {
	return fmt.Sprintf("request body exceeds the maximum size of %d bytes", e.limit)
}

func New(cfg config.Config, svc *service.Service) *Server {
	server := &Server{
		config:  cfg,
		service: svc,
		router:  mux.NewRouter(),
	}
	server.routes()
	return server
}

func (s *Server) Handler() http.Handler {
	return s.router
}

func (s *Server) Mount(pathPrefix string, handler http.Handler) {
	s.router.PathPrefix(pathPrefix).Handler(handler)
}

func (s *Server) routes() {
	s.router.HandleFunc("/", s.handleIndex).Methods(http.MethodGet)
	s.router.HandleFunc("/ui", s.handleIndex).Methods(http.MethodGet)
	s.router.HandleFunc("/v1/health", s.handleHealth).Methods(http.MethodGet)
	s.router.HandleFunc("/v1/config/public", s.handlePublicConfig).Methods(http.MethodGet)
	s.router.HandleFunc("/v1/test-connection", s.handleTestConnection).Methods(http.MethodPost)
	s.router.HandleFunc("/v1/mask", documentResponse(s.handleMask)).Methods(http.MethodPost)
	s.router.HandleFunc("/v1/jobs", documentResponse(s.handleCreateJob)).Methods(http.MethodPost)
	s.router.HandleFunc("/v1/jobs/{job_id}", documentResponse(s.handleGetJob)).Methods(http.MethodGet)
	// HEAD is opened on the result only: http.ServeContent already answers it with the
	// same headers and no body, so download managers and proxies can probe size and
	// existence. The JSON endpoints do not set Content-Length themselves, so HEAD
	// would mean something different there and stays closed.
	s.router.HandleFunc("/v1/jobs/{job_id}/result", documentResponse(s.handleGetJobResult)).Methods(http.MethodGet, http.MethodHead)
	s.router.HandleFunc("/v1/history", documentResponse(s.handleHistory)).Methods(http.MethodGet)
}

// documentResponse wraps the endpoints whose responses carry an uploaded document or
// the metadata derived from it, which is the very PII the service was handed.
//
// Nothing on that path may keep a copy: a 200 response to a GET with no freshness
// directive is heuristically cacheable, and the result download hands out a
// Last-Modified that invites exactly that, so a shared proxy or the browser disk cache
// could still serve a masked file long after the retention sweep deleted it from disk.
// nosniff keeps a client from second-guessing the declared type on the way out.
func documentResponse(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Cache-Control", "no-store")
		w.Header().Set("X-Content-Type-Options", "nosniff")
		next(w, r)
	}
}

